#include "dual_state_cuda_probe.cuh"
#include <random>
#include <cstdio>
int main(){try{using namespace tao::dual;Config c;c.layers=2;c.d=16;c.s=8;c.m=16;c.e=32;c.vocab=261;CpuModel cpu(c);CudaProbeModel gpu(c);std::mt19937 rng(819);std::normal_distribution<float>d(0,.1f);for(auto&kv:cpu.w)for(float&x:kv.second)x=kv.first.find("norm")!=std::string::npos?1.f:d(rng);gpu.w=cpu.w;auto a=cpu.initial(),b=gpu.initial();double worst=0;size_t checks=0;auto compare=[&](const Vec&x,const Vec&y){for(size_t j=0;j<x.size();++j){double err=std::abs(x[j]-y[j]);if(!std::isfinite(err)||err>2e-5*(1+std::abs(x[j])))throw std::runtime_error("parity");worst=std::max(worst,err);++checks;}};for(int i=0;i<32;++i){unsigned token=rng()%261;compare(cpu.step(token,a),gpu.step(token,b));for(unsigned l=0;l<c.layers;++l){compare(a[l].s,b[l].s);compare(a[l].m,b[l].m);}}printf("PASS checks=%zu max_abs=%.9g CUDA matrix/norm with host nonlinearities\n",checks,worst);return 0;}catch(const std::exception&e){printf("FAIL %s\n",e.what());return 1;}}
